codeExamples.code:
-- Enable continuous small-file management on the table
ALTER TABLE sales SET TBLPROPERTIES (
  'delta.autoOptimize.optimizeWrite' = 'true',   -- write larger files inline
  'delta.autoOptimize.autoCompact'  = 'true'     -- compact small files after writes
);

-- Batch compaction (bin-packing) of already-fragmented data,
-- scoped to a hot partition to keep it cheap
OPTIMIZE sales WHERE dt = '2026-07-02';

-- Compaction + data clustering for high-selectivity filters
OPTIMIZE sales WHERE dt = '2026-07-02' ZORDER BY (customer_id);

-- Old small files are tombstoned but still on disk; reclaim after retention
VACUUM sales RETAIN 168 HOURS;   -- keep 7 days for time-travel/long readers
